-- | @FiringFailed.error@ for exceptions raised by user code, against the
-- reference's @firing_failure_text@.
--
-- @differential/failure_text_corpus.json@ is generated by
-- @differential/failure_text_corpus.py@ from the pinned Python reference:
-- each case is an exception class name, its @args@, and the text the
-- reference records. Every case is rebuilt as a 'PythonException'; the cases
-- with no argument or one string argument are also thrown as Haskell
-- exceptions of that name, whose spelling must agree.
module Petrus.Impetus.FailureTextSpec (spec) where

import Control.Exception (ErrorCall (..), Exception (..), SomeException, evaluate, throw, toException, try)
import Control.Monad (forM_)
import Data.Bits (shiftL, shiftR, (.&.), (.|.))
import Data.ByteString (ByteString)
import Data.ByteString qualified as BS
import Data.Char (ord)
import Data.Text (Text)
import Data.Text qualified as T
import Numeric (readHex)
import Petrus.Impetus.History
import Petrus.Impetus.Instance
import Petrus.Impetus.InstanceSupport
import Petrus.Impetus.NetDefinitionCorpusSpec (findPackageFile)
import Petrus.Impetus.Petrinet hiding (candidates, candidatesWithDiagnostics, nextMaturation)
import Petrus.Impetus.TestSupport hiding (enabledTransitions)
import Petrus.Json
import Test.Hspec

-- Haskell exception types named like the reference's classes: the message
-- is the one string argument.
newtype ValueError = ValueError String deriving stock (Show)

instance Exception ValueError where displayException (ValueError m) = m

newtype KeyError = KeyError String deriving stock (Show)

instance Exception KeyError where displayException (KeyError m) = m

newtype RuntimeError = RuntimeError String deriving stock (Show)

instance Exception RuntimeError where displayException (RuntimeError m) = m

data Case = Case {name :: Text, arguments :: [PythonArg], text :: Text}

spec :: Spec
spec = describe "FiringFailed.error for raised exceptions (firing_failure_text)" $ do
  path <- runIO (findPackageFile ["differential/failure_text_corpus.json", "packages/petrus-impetus/differential/failure_text_corpus.json"])
  cases <- runIO (BS.readFile path >>= either fail pure . loadCorpus)
  it "covers the corpus" (length cases `shouldSatisfy` (> 400))
  forM_ (zip [0 :: Int ..] cases) $ \(index, c) -> do
    it ("case " <> show index <> ": " <> T.unpack (T.take 60 c.text)) $
      pythonFailureText (PythonException c.name c.arguments) `shouldBe` c.text
    forM_ (haskellTwin c) $ \exception ->
      it ("case " <> show index <> " thrown as a Haskell exception") $
        exceptionFailureText exception `shouldBe` c.text

  it "spells a thrown error call without its call stack" $ do
    raised <- try (evaluate (error "boom" :: ()))
    either exceptionFailureText (const "") raised `shouldBe` "ErrorCall('boom')"

  describe "through an inline step" $ do
    let pa = np "a"
        pb = np "b"
        tt = np "t"
        net = netOf [place pa, place pb] [(transition tt) {handler = Just (HandlerSymbol "h")}] [arc pa tt, arc tt pb]
        failing handler expected = do
          inst <-
            seededWith
              net
              defaultInstanceConfig
                { initialMarking = markingFromList [(pa, [tok "X"])]
                , handlerImplementations = symbolHandlers [("h", handler)]
                }
          raised <- step inst Nothing >>= expectHandlerRaised
          raised `shouldBe` expected
          records <- historyOf inst
          last records `shouldBe` RFiringFailed (FiringFailed tt expected 1 0)
    it "records Name() for an exception with an empty message" $
      failing (\_ _ -> throw (ErrorCall "")) "ErrorCall()"
    it "records Name('message') for an exception with a message" $
      failing (\_ _ -> throw (KeyError "amount")) "KeyError('amount')"
    it "records a PythonException exactly" $
      failing (\_ _ -> throw (PythonException "KeyError" [PyStr "amount", PyInt 3, PyObject "builtins" "object"])) "KeyError('amount', 3, <builtins.object>)"

-- | The Haskell exception the reference's case corresponds to, when there
-- is one: a known class name with no argument or one string argument.
haskellTwin :: Case -> [SomeException]
haskellTwin c = case c.arguments of
  [] -> maybe [] pure (named "")
  [PyStr message] | not (T.null message) -> maybe [] pure (named (T.unpack message))
  _ -> []
  where
    named message = case c.name of
      "ErrorCall" -> Just (toException (ErrorCall message))
      "ValueError" -> Just (toException (ValueError message))
      "KeyError" -> Just (toException (KeyError message))
      "RuntimeError" -> Just (toException (RuntimeError message))
      _ -> Nothing

-- ---------------------------------------------------------------------------
-- Loading

loadCorpus :: ByteString -> Either String [Case]
loadCorpus raw = do
  corpus <- parseJson surrogateRefusingLoads raw
  items <- case lookupMember "cases" corpus of
    Just (Array items) -> Right items
    _ -> Left "corpus has no cases"
  traverse loadCase items

loadCase :: Json -> Either String Case
loadCase value = do
  name <- member "name" >>= string
  arguments <- member "args" >>= \case
    Array items -> traverse argument items
    _ -> Left "args is not a list"
  text <- member "text" >>= string
  Right Case {name, arguments, text}
  where
    member key = maybe (Left ("case lacks " <> T.unpack key)) Right (lookupMember key value)

argument :: Json -> Either String PythonArg
argument = \case
  Object [("none", Null)] -> Right PyNone
  Object [("bool", Bool b)] -> Right (PyBool b)
  Object [("int", String digits)] -> Right (PyInt (integer digits))
  Object [("float", String spelled)] -> Right (PyFloat (float spelled))
  Object [("str", String s)] -> Right (PyStr s)
  Object [("bytes", String b)] -> Right (PyBytes (decodeBase64 b))
  Object [("object", Array [String modul, String qualname])] -> Right (PyObject modul qualname)
  other -> Left ("unknown argument " <> show other)

string :: Json -> Either String Text
string = \case
  String t -> Right t
  other -> Left ("expected a string, got " <> show other)

-- | A decimal or (for huge values) @hex()@ spelling.
integer :: Text -> Integer
integer spelled = case T.unpack spelled of
  '-' : rest -> negate (unsigned rest)
  rest -> unsigned rest
  where
    unsigned = \case
      '0' : 'x' : digits -> fst (head' (readHex digits))
      digits -> read digits
    head' = \case
      x : _ -> x
      [] -> error ("bad integer " <> T.unpack spelled)

-- | @float.hex()@, or @nan@ / @inf@ / @-inf@.
float :: Text -> Double
float = \case
  "nan" -> 0 / 0
  "inf" -> 1 / 0
  "-inf" -> -1 / 0
  spelled -> case T.unpack spelled of
    '-' : rest -> negate (unsignedHex rest)
    rest -> unsignedHex rest
  where
    unsignedHex s =
      let (mantissa, exponent') = break (== 'p') (drop 2 s)
          (whole, fraction) = break (== '.') mantissa
          digits = whole <> drop 1 fraction
          value = case readHex digits of
            (v, _) : _ -> v :: Integer
            [] -> error ("bad float " <> s)
          scale = read (dropWhile (== '+') (drop 1 exponent')) - 4 * length (drop 1 fraction)
       in if scale >= 0 then fromInteger (value * 2 ^ scale) else fromRational (fromInteger value / 2 ^ negate scale)

decodeBase64 :: Text -> ByteString
decodeBase64 = BS.pack . go . map sextet . filter (/= '=') . T.unpack
  where
    sextet ch
      | ch >= 'A' && ch <= 'Z' = ord ch - ord 'A'
      | ch >= 'a' && ch <= 'z' = ord ch - ord 'a' + 26
      | ch >= '0' && ch <= '9' = ord ch - ord '0' + 52
      | ch == '+' = 62
      | otherwise = 63
    go (a : b : c : d : rest) = triple a b c d 3 <> go rest
    go [a, b, c] = triple a b c 0 2
    go [a, b] = triple a b 0 0 1
    go _ = []
    triple a b c d count =
      let n = (a `shiftL` 18) .|. (b `shiftL` 12) .|. (c `shiftL` 6) .|. d
       in take count [fromIntegral ((n `shiftR` 16) .&. 255), fromIntegral ((n `shiftR` 8) .&. 255), fromIntegral (n .&. 255)]
